import os,re,subprocess,urllib.parse
def audit_urls(repo,commit,allowed_hosts):
    if not isinstance(commit,str) or not re.fullmatch(r'[0-9a-f]{40}',commit):raise ValueError('literal approved SHA1 required')
    hosts=set(allowed_hosts)
    if not hosts or any(not isinstance(h,str) or not re.fullmatch(r'[a-z0-9][a-z0-9.-]*',h) for h in hosts):raise ValueError('explicit lowercase host policy required')
    env={k:v for k,v in os.environ.items() if not k.startswith('GIT_')};env.update(GIT_CONFIG_NOSYSTEM='1',GIT_CONFIG_GLOBAL=os.devnull,GIT_TERMINAL_PROMPT='0',GIT_OPTIONAL_LOCKS='0')
    result=subprocess.run(['git','-C',str(repo),'config','--no-includes','--blob',commit+':.gitmodules','-z','--get-regexp',r'^submodule\..*\.url$'],env=env,capture_output=True,text=True,timeout=5)
    if result.returncode not in (0,1):raise ValueError('committed submodule config unreadable')
    rows=[]
    for record in result.stdout.split(chr(0)):
        if not record:continue
        key,url=record.split('\n',1);allowed=False
        if not any(ord(c)<32 or ord(c)==127 for c in url):
            try:
                target=urllib.parse.urlsplit(url)
                allowed=target.scheme=='https' and target.username is None and target.password is None and target.hostname in hosts and target.port in (None,443) and not target.query and not target.fragment and re.fullmatch(r'/approved/[A-Za-z0-9][A-Za-z0-9_.-]*\.git',target.path) is not None
            except ValueError:pass
        rows.append({'key':key,'url':url,'allowed':allowed})
    return rows
```

